import std.concurrent as conc

pub type AppError = Failed(String)

pub fn main() -> Result<(), AppError> {
    let a: conc.Channel<Int64> = conc.channel(4)
    let b: conc.Channel<Int64> = conc.channel(4)
    let v = select {
        case x = a.receive() => x
        case y = b.receive() => y
    }
    let w = select {
        case _ = a.receive() => 1
        case _ = b.receive() => 2
    }
    let _ = v
    let _ = w
    return Ok(())
}

